      type: "workspace",
      id: parsedInput.workspaceId,
    });

    // New webhook, use the provided secret or generate a new one
    secret = parsedInput.secret ?? generateWebhookSecret();
  }

  await testEndpoint(parsedInput.url, secret);
  return { success: true, secret };
});

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { duplicateWebhook } from "../lib/api-client";

export const useDuplicateWebhook = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ webhookId, workspaceId }: { webhookId: string; workspaceId: string }) =>
      duplicateWebhook({ webhookId, workspaceId }),
    onSuccess: () => {
      // Invalidate webhook list queries so the new webhook appears in the table.
      queryClient.invalidateQueries({ queryKey: ["webhooks"] });
    },
  });
};

import { parseV3ApiError } from "@/modules/api/lib/v3-client";

const JSON_HEADERS = { "Content-Type": "application/json" };

/**
 * Client fetchers for the Webhooks v3 routes. Every call throws a parsed `V3ApiError` on a
 * non-2xx response.
 */

export async function duplicateWebhook(params: {
  webhookId: string;
  workspaceId: string;
}): Promise<unknown> {
  const url = `/api/v3/webhooks/${params.webhookId}/duplicate?workspaceId=${encodeURIComponent(params.workspaceId)}`;

  const response = await fetch(url, {
    method: "POST",
    cache: "no-store",
    headers: JSON_HEADERS,
    signal: AbortSignal.timeout(15_000),
  });

  if (!response.ok) {
    throw await parseV3ApiError(response);
  }

  const body = (await response.json()) as { data: unknown };
  return body.data;
}

/**
 * POST /api/v3/webhooks/{webhookId}/duplicate — clone an existing webhook into the same workspace.
 *
 * Reads the source webhook, constructs a new input with `Copy of <name>`, and delegates to the
 * service-layer `createWebhook`. Mirrors the audit / rate-limit / authorization that the legacy
 * server action performed.
 */
import { z } from "zod";
import { ZId } from "@formbricks/types/common";
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { generateWebhookSecret } from "@/lib/crypto";
import { assertCan } from "@/lib/authorization";
import { getOrganizationIdFromWebhookId, getWorkspaceIdFromWebhookId } from "@/lib/utils/helper";
import { getWebhook } from "@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { createWebhook } from "@/modules/integrations/webhooks/lib/webhook";
import { ZWebhookInput } from "@/modules/integrations/webhooks/types/webhooks";

export const POST = withV3ApiWrapper({
  auth: "session",
  action: "created",
  targetType: "webhook",
  schemas: {
    params: z.object({ webhookId: ZId }),
    query: z.object({ workspaceId: ZId }),
  },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) => {
    const { webhookId } = parsedInput.params;
    const { workspaceId } = parsedInput.query;

    const organizationId = await getOrganizationIdFromWebhookId(webhookId);
    const sourceWorkspaceId = await getWorkspaceIdFromWebhookId(webhookId);

    await assertCan({ type: "user", id: authentication.userId }, "workspace.write", {
      type: "workspace",
      id: sourceWorkspaceId,
    });
    await applyRateLimit(rateLimitConfigs.actions.stateMutation, sourceWorkspaceId);

    const sourceWebhook = await getWebhook(webhookId);
    if (!sourceWebhook.ok) {
      return new Response(
        JSON.stringify({
          error: "not_found",
          detail: `Webhook ${webhookId} not found`,
        }),
        { status: 404, headers: { "Content-Type": "application/json" } }
      );
    }

    const newWebhookInput: ZWebhookInput = {
      name: sourceWebhook.data.name ? `Copy of ${sourceWebhook.data.name}` : undefined,
      url: sourceWebhook.data.url,
      triggers: sourceWebhook.data.triggers,
      surveyIds: sourceWebhook.data.surveyIds,
    };

    const newWebhook = await createWebhook(workspaceId, newWebhookInput, generateWebhookSecret());

    auditLog.webhookId = webhookId;
    auditLog.newObject = newWebhookInput;
    auditLog.organizationId = organizationId;

    return new Response(JSON.stringify({ data: newWebhook }), {
      status: 201,
      headers: { "Content-Type": "application/json" },
    });
  },
});

"use client";

import { DuplicateIcon } from "lucide-react";
import { TFunction } from "i18next";
import { useRouter } from "next/navigation";
import { useTranslation } from "react-i18next";
import { Webhook } from "@formbricks/database/prisma-browser";
import { TSurvey } from "@formbricks/types/surveys/types";
import { timeSince } from "@/lib/time";
import { getFormattedErrorMessage } from "@/lib/utils/error-message";
import { RestrictedSurveyHint } from "@/modules/survey/visibility/components/restricted-survey-hint";
import { hasRestrictedAttachedSurvey } from "@/modules/survey/visibility/lib/outbound";
import { Badge } from "@/modules/ui/components/badge";
import { Button } from "@/modules/ui/components/button";
import { useDuplicateWebhook } from "../hooks/use-duplicate-webhook";
import { toast } from "react-hot-toast";

const renderSelectedSurveysText = (webhook: Webhook, allSurveys: TSurvey[]) => {
  let surveyNames: string[];

  if (webhook.surveyIds.length === 0) {
    return null;
  }

  surveyNames = webhook.surveyIds
    .map((id) => {
      const survey = allSurveys.find((s) => s.id === id);
      return survey?.name ?? id;
    })
    .filter(Boolean);

  if (surveyNames.length === 0) {
    return null;
  }

  if (surveyNames.length < 3) {
    return surveyNames.join(", ");
  }

  return (
    <span className="flex items-center gap-x-1">
      {surveyNames.slice(0, 2).join(", ")}
      <span className="text-slate-400">
        , +{surveyNames.length - 2} more
      </span>
    </span>
  );
};

const renderSelectedTriggersText = (webhook: Webhook, t: TFunction) => {
  const triggerLabels: Record<string, string> = {
    responseAdded: t("workspace.integrations.webhooks.trigger_response_added"),
    responseUpdated: t("workspace.integrations.webhooks.trigger_response_updated"),
  };

  return webhook.triggers
    .map((trigger) => triggerLabels[trigger] ?? trigger)
    .join(", ");
};

export const WebhookRowData = ({
  webhook,
  surveys,
  surveyVisibilityEnabled,
}: Readonly<{ webhook: Webhook; surveys: TSurvey[]; surveyVisibilityEnabled: boolean }>) => {
  const { t, i18n } = useTranslation();
  const router = useRouter();
  const locale = i18n.resolvedLanguage ?? i18n.language ?? "en-US";
  const { mutate: duplicateWebhook, isPending: isDuplicating } = useDuplicateWebhook();

  const handleDuplicate = async () => {
    try {
      const result = await duplicateWebhook({ webhookId: webhook.id, workspaceId: webhook.workspaceId });
      if (result) {
        toast.success(t("workspace.integrations.webhooks.webhook_duplicated_successfully"));
        router.refresh();
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "Unknown error occurred";
      toast.error(getFormattedErrorMessage({ error: errorMessage }));
    }
  };

  return (
    <div className="mt-2 grid h-auto grid-cols-12 content-center rounded-lg py-2 hover:bg-slate-100">
      <div className="col-span-3 my-auto flex min-w-0 items-center gap-x-2 text-sm text-slate-800">
        <span className="truncate font-medium">{webhook.name}</span>
        {webhook.url && (
          <span className="truncate text-slate-400">{webhook.url}</span>
        )}
      </div>
      <div className="col-span-1 my-auto text-center text-sm text-slate-800">
        <Badge type="gray" size="tiny" text={webhook.source || t("common.user")} className="capitalize" />
      </div>
      <div className="col-span-3 my-auto flex min-w-0 items-center justify-center gap-x-2 text-sm text-slate-800">
        {renderSelectedSurveysText(webhook, surveys)}
        {hasRestrictedAttachedSurvey(surveyVisibilityEnabled, webhook.surveyIds, surveys) && (
          <RestrictedSurveyHint kind="paused" />
        )}
      </div>
      <div className="col-span-2 my-auto text-center text-sm text-slate-800">
        {renderSelectedTriggersText(webhook, t)}
      </div>
      <div className="col-span-1 my-auto text-center text-sm whitespace-nowrap text-slate-500">
        {timeSince(webhook.createdAt.toString(), locale)}
      </div>
      <div className="col-span-1 my-auto text-center text-sm whitespace-nowrap text-slate-500">
        {timeSince(webhook.updatedAt.toString(), locale)}
      </div>
      <div className="col-span-1 my-auto text-center">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          disabled={isDuplicating}
          loading={isDuplicating}
          onClick={handleDuplicate}
          className="h-8 w-8 p-0"
          title={t("workspace.integrations.webhooks.duplicate_webhook")}>
          <DuplicateIcon className="size-4 text-slate-500" />
        </Button>
      </div>
    </div>
  );
};

